function Halo({ x, y, r = 70 }: { x: number; y: number; r?: number }) {
  return <circle className="cn-art-halo" cx={x} cy={y} r={r} fill="#f0ce7b" fillOpacity=".1" stroke="#d6ad57" strokeOpacity=".65" strokeWidth="2.5" strokeDasharray="5 9" />;
}

function Caption({ x, y, children }: { x: number; y: number; children: ReactNode }) {
  return <text x={x} y={y} fill={ink} textAnchor="middle" fontSize="23" fontFamily="serif" letterSpacing="3">{children}</text>;
}

function Rain({ heavy = false }: { heavy?: boolean }) {
  return <g className="cn-art-rain" stroke="#a0b3a5" strokeWidth="2" strokeLinecap="round" opacity=".55">{Array.from({length: heavy ? 45 : 24},(_,i) => <path key={i} d={`m${32+(i*83)%848} ${65+(i*43)%388} -8 23`} />)}</g>;
}

