const descriptions: Record<number, string[]> = {
  1: ['孩子们沿花路来到树木环绕的校园，彼此招手。', '孩子们在教室认真读书，窗外的小鸟安静停着。', '下课后的校园，孩子们奔跑、游戏。', '校园的铜钟、大树、白墙与凤尾竹。'],
  2: ['雨点落在草地上的各色花朵间。', '想象中的地下学校，花孩子坐在小木桌旁做功课。', '孩子想象各色花朵长出手脚，在草地上跳舞。', '想象中的花孩子向云朵伸出手。'],
  3: ['旧学堂里，老师和孩子们正在读书。', '一名孩子举起手，向老师提问。', '老师转向举手的孩子，开始讲解。', '同学们围着书本交流问题。'],
  4: ['古诗情境：秋山石径、湖中青山或夜色中的灯火。', '古诗中主要景物在画面中突出显示。'],
  5: ['雨后树木间的水泥道，路上有水洼与落叶。', '近距离观察水泥道上金黄、红褐的落叶。', '各色落叶铺在水泥道上，像一块彩色地毯。', '一双棕红小靴子轻轻走在铺满落叶的水泥道上。'],
  6: ['秋雨和一把想象中的钥匙，打开了秋天的大门。', '秋雨为树叶染上金黄、橙红的颜色。', '秋雨里的果园挂着梨和橘子，孩子闻着果香。', '动物们整理巢穴，准备过冬。'],
  7: ['秋风吹过落叶和田野。', '草丛里的蟋蟀在鸣叫。', '大雁排成队伍飞过秋日天空。', '秋叶、小花、谷粒和田野。'],
  8: ['一座年老的屋子，墙壁开裂，门前没有来客。', '一只小猫来到老屋门前。', '一只母鸡带着小鸡来到老屋门前。', '蜘蛛在老屋的屋檐下织网。'],
  9: ['乌龟在小路上开始旅行，两只鸽子在身旁。', '乌龟在路上遇见蜘蛛。', '蜗牛和路标为乌龟指路。', '乌龟在沙地遇见壁虎，仍决定向前。'],
  10: ['一只小狗独自站在乡间小路上。', '小狗遇见鸣叫的公鸡。', '小狗仰望树上的鸟，学习叫声。', '小狗面对乡间岔路，后面的故事等待阅读。'],
  11: ['奶奶坐在屋旁讲故事，孩子认真听着。', '孩子的想象泡泡里出现桃子、鱼和宝葫芦。', '孩子的想象泡泡里出现自动写满的书本。', '孩子想象新的宝葫芦故事。'],
  12: ['红头和青头两只蟋蟀在牛旁的草地上。', '青头爬在牛背上，向遇险的红头提醒与安慰。', '虚线在牛的场景外标出故事中的旅行方向，不表示消化器官。', '牛打喷嚏，青头在牛鼻边帮助红头，两只蟋蟀重新相聚。'],
  13: ['一群蚂蚁搬动一大块奶酪。', '奶酪掉下一小角，蚂蚁队长在旁边。', '蚂蚁队长召集蚂蚁们回到队伍。', '最小的蚂蚁得到掉下来的奶酪小角。'],
  14: ['翠鸟停在船头，翠绿羽毛、蓝色翅膀和红色长嘴清晰可见。', '翠鸟斜着扎入河水，水面溅起水花。', '翠鸟从水面飞起，长嘴里衔着小鱼。', '翠鸟吞下小鱼后，空着嘴停在船头。'],
  15: ['蒲公英展开金色花瓣，草地呈现金黄。', '蒲公英花瓣合拢，草地呈现绿色。', '阳光下蒲公英再次展开金色花瓣。', '早晨、中午、傍晚的蒲公英并排比较，合拢、展开、合拢。'],
  16: ['青绿海水环绕海岛，海水有不同深浅的色带。', '海底形状不同的珊瑚和各色鱼群。', '近距离观察成群的、样子不同的鱼。', '海岛树上有鸟巢，鸟儿从天空飞过。'],
  17: ['海边有船只、飞鸟和沙滩上的贝壳。', '海滨庭院里有大树、花草和房屋。', '海滨公园里，榕树的树冠为长椅遮阴。', '海滨街道整洁开阔，道旁有树木和房屋。'],
  18: ['小兴安岭的春天，溪水流过残冰，花草生长。', '小兴安岭的夏天，浓密的树木间飘着雾。', '小兴安岭的秋天，叶子变红变黄，果实成熟。', '小兴安岭的冬天，树木和大地覆着白雪。'],
  19: ['香港港口，船只在楼群前的水面行驶。', '香港街头丰富多样的食物。', '香港海边的金紫荆雕塑，游客在旁观察。', '香港夜景，楼宇灯光映照在海面上。'],
  20: ['古诗情境：森林光影、江流两山或晴雨湖色。', '古诗中正在观察的景物突出显示。'],
  21: ['风、流水、鸟与虫组成大自然的音乐场景。', '风穿过树木，吹动树叶。', '水流经过石头，雨滴落入小溪。', '鸟在枝头鸣唱，虫在草丛中鸣叫。'],
  22: ['孩子仰望树枝上的鸟，留意它们的声音和样子。', '孩子通过放大镜观察草地上的昆虫。', '孩子观察不同颜色的花朵与树木。', '孩子观察竹子，并把花朵和昆虫画进观察笔记。'],
  23: ['一群孩子在庭院的大瓮旁。', '一个孩子落入瓮中，露出头和双手，其他孩子在旁惊慌。', '一些孩子跑开，司马光仍留在瓮旁。', '大瓮破口流出水，孩子们扶住获救的同伴。'],
  24: ['童第周在校园认真读书。', '夜晚的路灯下，童第周继续认真学习。', '童第周通过显微镜观察实验材料。', '实验桌上的观察器皿和材料被放大突出。'],
  25: ['战地帐篷里，医护人员在盖着白布的手术台旁工作，画面没有伤口。', '远处出现烟雾，医生仍专注于手术。', '一位战士来到帐篷前，医生继续工作。', '医生和护士继续协作救治。'],
  26: ['博物馆展柜里展示着一只磨损的粗瓷大碗。', '一只装着饭的粗瓷碗，在炊事员与赵一曼之间传递。', '赵一曼把饭拨回锅里，旁边放着盛野菜粥的碗。', '几名战士围在桌边，共用粗瓷碗盛菜。'],
};

/** Original story illustrations. Each stage contains only the characters already introduced. */
export default function ChineseLessonArt({ courseId, step, variant = '' }: Props) {
  const uid = useId().replace(/:/g, '');
  const n = Number(courseId.match(/\d+/)?.[0]) || 1;
  const poemVariant = variant.toLowerCase().replace(/[-_\s]/g, '');
  const s = Math.max(0, Math.floor(step));
  const stages = descriptions[n] || descriptions[1];
  const describedPoem = poemVariant || (n === 4 ? ['wangdongting', 'shanxing', 'yeshusuojian', 'shanxing'][Math.min(s, 3)] : n === 20 ? ['luchai', 'wangtianmenshan', 'yinhushang', 'yinhushang'][Math.min(s, 3)] : '');
  let label = stages[Math.min(s, stages.length - 1)];
  if (n === 4) label = describedPoem.includes('wangdongting') ? '望洞庭：月光下，平静的湖面映着青绿的君山，小舟从远处经过。' : describedPoem.includes('yeshusuojian') ? '夜书所见：秋风吹过树叶，夜色里屋窗透出灯光，孩子在草丛边寻找蟋蟀。' : '山行：弯曲的石径通向秋山深处，白云间藏着人家，旅人在枫林旁停下车。';
  if (n === 20) label = describedPoem.includes('wangtianmenshan') ? '望天门山：两座青山分立江边，江水流过山口，一叶帆船驶来。' : describedPoem.includes('yinhushang') ? (poemVariant && s === 1) || (!poemVariant && s === 2) ? '饮湖上初晴后雨：雨丝和薄雾中的湖水与远山。' : '饮湖上初晴后雨：阳光下的湖面闪着水光，远山与小舟相映。' : '鹿柴：空山树林里没有人，夕阳的光穿过树间，照在青苔上。';
  return <svg className="chinese-lesson-art" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 900 600" width="100%" preserveAspectRatio="xMidYMid meet" role="img" aria-label={label} data-course={courseId} data-step={s}>
    <title>{label}</title>
    <defs><filter id={`${uid}-paper`} x="0" y="0" width="100%" height="100%"><feTurbulence type="fractalNoise" baseFrequency=".72" numOctaves="3" seed="8" /><feColorMatrix type="saturate" values="0" /><feComponentTransfer><feFuncA type="linear" slope=".045" /></feComponentTransfer><feBlend in="SourceGraphic" mode="multiply" /></filter></defs>
    <g className="cn-art-stage" key={`${courseId}-${s}-${variant}`}><Scene n={n} s={s} variant={poemVariant} /></g>
    <rect width="900" height="600" fill="#b7a98a" opacity=".16" filter={`url(#${uid}-paper)`} pointerEvents="none" />
    <path d="M17 12H884V587H17Z" fill="none" stroke="#9b8e6f" strokeOpacity=".17" strokeWidth="2" pointerEvents="none" />
  </svg>;
}
